dden}.motto{position:relative;z-index:5;margin-top:6px;color:#e2c478;font-size:9px;font-style:italic;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.portrait-box{position:absolute;z-index:8;top:108px;left:50%;transform:translateX(-50%);width:162px;height:198px;padding:6px;background:#f5f0e6;border:2px solid #b98d38;box-shadow:0 5px 12px rgba(26,28,32,.15)}.portrait{width:100%;height:100%;object-fit:cover;object-position:top;background:#d8d3ca}.fallback{height:100%;display:grid;place-items:center;background:#d8d3ca;font-size:64px;color:var(--navy);font-weight:bold}.name{position:absolute;top:316px;left:20px;right:20px;text-align:center;text-transform:uppercase;font-size:22px;line-height:1;font-weight:bold;letter-spacing:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.role{position:absolute;top:346px;left:24px;right:24px;text-align:center;text-transform:uppercase;color:var(--wine);font:800 10px Arial,sans-serif;letter-spacing:2px;white-space:nowrap;overflow:hidden}.details{position:absolute;top:379px;left:42px;right:42px;border-collapse:collapse;font-family:Arial,sans-serif}.details td{padding:7px 0;border-bottom:1px solid #d1b57e;font-size:10px}.details td:first-child{width:96px;color:var(--wine);font-size:8px;font-weight:900;letter-spacing:.8px;text-transform:uppercase}.details td:last-child{border-left:1px solid #d1b57e;padding-left:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:125px}.foot{position:absolute;left:0;right:0;bottom:0;height:45px;background:var(--wine);border-top:3px solid var(--gold);color:#e7c674;text-align:center;padding-top:13px;font-size:15px;letter-spacing:10px;font-weight:bold}.back .frame{inset:12px}.frame2{position:absolute;inset:18px;border:1px solid #ddc99b}.back-school{position:absolute;top:48px;left:30px;right:30px;text-align:center;text-transform:uppercase;font-size:23px;line-height:.95;letter-spacing:2px;font-weight:bold;max-height:48px;overflow:hidden}.ornament{position:absolute;top:1